import z from "zod";

/** Where a post came from. `own` is written in the admin panel; `github` and
 * `linkedin` posts are generated by their sync workers. */
export const postSourceSchema = z.enum(["own", "github", "linkedin"]);

/** A post is a draft until it is published; only published posts are public. */
export const postStatusSchema = z.enum(["draft", "published"]);

/** The GitHub event a generated post was distilled from. */
export const githubMetaSchema = z.object({
  action: z.string(),
  commitSha: z.string().nullable(),
  language: z.string().nullable(),
  repo: z.string(),
  stars: z.number().int().nullable(),
  url: z.url(),
});

/** The LinkedIn post a generated post mirrors. */
export const linkedinMetaSchema = z.object({
  permalink: z.url(),
  postedAt: z.iso.datetime().nullable(),
});

/** A post as the public feed and the admin list render it. */
export const postSummarySchema = z.object({
  coverImage: z.string().nullable(),
  createdAt: z.iso.datetime(),
  excerpt: z.string().nullable(),
  externalUrl: z.string().nullable(),
  githubMeta: githubMetaSchema.nullable(),
  id: z.uuid(),
  linkedinMeta: linkedinMetaSchema.nullable(),
  publishedAt: z.iso.datetime().nullable(),
  readTimeMin: z.number().int(),
  slug: z.string().nullable(),
  source: postSourceSchema,
  status: postStatusSchema,
  tags: z.array(z.string()),
  title: z.string(),
  updatedAt: z.iso.datetime(),
});

/** A single post page: the summary plus the markdown body and its rendered
 * HTML. Both are nullable because generated posts carry no body. */
export const postDetailSchema = postSummarySchema.extend({
  body: z.string().nullable(),
  bodyHtml: z.string().nullable(),
});

/** Cursor-paginated query for the public feed. */
export const postsListQuerySchema = z.object({
  cursor: z.string().max(512).optional(),
  limit: z.number().int().min(1).max(50).default(20),
  q: z.string().max(200).optional(),
  sources: z.array(postSourceSchema).optional(),
  tag: z.string().max(64).optional(),
  year: z.number().int().min(2000).max(2100).optional(),
});

/** The public feed page: summaries, the total matching the filter, and the
 * cursor for the next page (null on the last page). */
export const postsListResponseSchema = z.object({
  items: z.array(postSummarySchema),
  nextCursor: z.string().nullable(),
  total: z.number(),
});

/** A hand-written or LinkedIn-sourced post. GitHub posts are sync-only and
 * cannot be created through the API. */
export const postCreateSchema = z.object({
  body: z.string().max(100_000).nullable().default(null),
  coverImage: z.string().max(500).nullable().default(null),
  excerpt: z.string().max(400).nullable().default(null),
  externalUrl: z.string().max(500).nullable().default(null),
  linkedinPermalink: z.url().nullable().default(null),
  slug: z.string().max(120).nullable().default(null),
  source: z.enum(["own", "linkedin"]),
  tags: z.array(z.string().max(48)).max(12).default([]),
  title: z.string().min(1).max(200),
});

/** A patch to an existing post; `id` names the row. */
export const postUpdateSchema = postCreateSchema.partial().extend({
  id: z.uuid(),
});

export const postBySlugSchema = z.object({ slug: z.string().min(1) });

export const postRelatedSchema = z.object({ slug: z.string().min(1) });
